mapper.select:
select
,pd.sku_no,pd.name as productName,pd.images_url as imagesUrl from purchase_suggest ps left join purchase_suggest_sys pss on ps.id = pss.source_id and pss.is_deleted = false left join product_detail pd on ps.sku_id = pd.id and pd.is_deleted = false
ps.is_deleted = false and ps.status = 'draft' and ps.source_id = #{params.sourceId}

select
from purchase_suggest ps left join purchase_suggest_sys pss on ps.id = pss.source_id and pss.is_deleted = false
ps.is_deleted = false and ps.status = 'draft' and ps.invalid_status = false AND NOT EXISTS ( SELECT 1 FROM purchase_suggest_merge psm WHERE psm.is_deleted = FALSE AND ps.id = ANY (SELECT jsonb_array_elements_text(psm.source_id_json)::text) );
